[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ProjectPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest;$ProjectPath=[IO.Path]::GetFullPath($ProjectPath);$utf8=New-Object Text.UTF8Encoding($false,$true)
function Hash([string]$Path){(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()}
function Atomic([string]$Path,[object]$Value){if(Test-Path $Path){throw "Create-new evidence target exists: $Path"};$text=($Value|ConvertTo-Json -Depth 25).Replace("`r`n","`n").Replace("`r","`n")+"`n";$tmp=$Path+'.tmp.'+[Guid]::NewGuid().ToString('N');[IO.File]::WriteAllText($tmp,$text,$utf8);[IO.File]::Move($tmp,$Path)}
$relative=@('Research\Gate13R_36h_10pct_4Lane_PrePilot_Defect_Repair_Amendment.v8.json','Research\Verification\New-Gate13R36hAttempt8GeneratorV1.ps1','Research\Gate13R_36h_10pct_4Lane_Attempt8_Generator_Derivation_Receipt.v1.json','Research\Verification\New-Gate13R36hAttempt8ArtifactsV1.ps1')
$files=@($relative|ForEach-Object{$p=Join-Path $ProjectPath $_;$i=Get-Item $p;[pscustomobject][ordered]@{relativePath=$_.Replace('\','/');bytes=[int64]$i.Length;lastWriteTimeUtc=$i.LastWriteTimeUtc.ToString('o');sha256=Hash $p}})
$manifestPath=Join-Path $ProjectPath 'Research\Gate13R_36h_10pct_4Lane_Attempt8_Derivation_Partial_Manifest.v1.json';$failurePath=Join-Path $ProjectPath 'Research\Gate13R_36h_10pct_4Lane_Attempt8_Derivation_Failure.v1.json';$checkpointPath=Join-Path $ProjectPath 'Research\Gate13R_36h_10pct_4Lane_Attempt8_Derivation_Checkpoint.v1.json'
$roots=[ordered]@{verification=Test-Path (Join-Path $ProjectPath 'Research\Verification\Gate13R_36h_10pct_4Lane\v8');pilot=Test-Path (Join-Path $ProjectPath 'Research\PilotRuns\Gate13R_36h_10pct_4Lane\v8');clone=Test-Path 'H:\DDM_Final_Project_Gate13R36H\v8';formal=Test-Path (Join-Path $ProjectPath 'Research\FormalRuns\Gate13R_36h_10pct_4Lane\v1')}
$manifest=[ordered]@{schemaVersion=1;manifestKind='gate13r-36h-attempt8-derivation-partial-manifest-v1';createdAtUtc=[DateTime]::UtcNow.ToString('o');status='FAILED-PRE-WRITE';files=$files;roots=$roots;unityProcessCount=@(Get-Process Unity -ErrorAction SilentlyContinue).Count;pilotStarted=$false;formalCampaign=$false;passed=$false};Atomic $manifestPath $manifest
$failure=[ordered]@{schemaVersion=1;receiptKind='gate13r-36h-attempt8-derivation-failure-v1';createdAtUtc=[DateTime]::UtcNow.ToString('o');status='FAILED-PRE-WRITE';phase='frozen-evidence-resolution';errorMessage='The generic v7-to-v8 route changed the historical attempt-2 static evidence path from PreImplementation/v7/StaticUnitV2 to the nonexistent PreImplementation/v8/StaticUnitV2.';allowedRepair='A new versioned attempt may restore the historical attempt-2 path to v7 before any output derivation.';partialManifestSha256=Hash $manifestPath;roots=$roots;unityProcessCount=$manifest.unityProcessCount;pilotStarted=$false;formalCampaign=$false;passed=$false};Atomic $failurePath $failure
$checkpoint=[ordered]@{schemaVersion=1;checkpointKind='gate13r-36h-attempt8-derivation-checkpoint-v1';createdAtUtc=[DateTime]::UtcNow.ToString('o');status='failed-no-resume';attempt=8;lastCompletedPhase='generator-derivation';failedPhase='frozen-evidence-resolution';failureReceiptSha256=Hash $failurePath;partialManifestSha256=Hash $manifestPath;nextAllowedAction='Create a new versioned attempt and keep historical PreImplementation/v7 attempt-2 paths fixed.';pilotStarted=$false;formalCampaign=$false;passed=$false};Atomic $checkpointPath $checkpoint
[pscustomobject]@{manifestSha256=Hash $manifestPath;failureSha256=Hash $failurePath;checkpointSha256=Hash $checkpointPath}|ConvertTo-Json
